// Cattasaurus Dashboard service worker — build c8b4463df2 (generated by build_site.py)
const BUILD = 'c8b4463df2';
const SHELL = 'ctu-shell-' + BUILD;   // pages + code + brand files of this build
const DATA = 'ctu-data-v1';           // last good /data/*.json, kept across builds
const PRECACHE = ['/', '/pnl', '/pnl.js?v=' + BUILD, '/offline.html', '/manifest.webmanifest',
  '/img/logo-h-pine.png', '/img/logo-h-pistachio.png', '/img/mascot-bag.png', '/img/mascot-shy.png', '/img/mascot-sidelook.png', '/img/mascot-lying.png', '/img/mascot-sleep.png',
  '/fonts/BureauGrot-CondMedium.woff2', '/fonts/LibreFranklin-Regular.woff2', '/fonts/LibreFranklin-SemiBold.woff2', '/fonts/FuzzyBubbles-Bold.woff2'];
const NEVER = new Set(['/login', '/logout', '/sw.js', '/robots.txt']);

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(SHELL);
    await Promise.all(PRECACHE.map((u) => c.add(new Request(u, { credentials: 'same-origin' })).catch(() => {})));   // best effort
    await self.skipWaiting();
  })());
});
self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('ctu-shell-') && k !== SHELL).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (NEVER.has(url.pathname)) { if (url.pathname === '/logout') e.waitUntil(caches.delete(DATA)); return; }
  if (url.pathname.startsWith('/data/')) { e.respondWith(dataFetch(e)); return; }
  if (req.mode === 'navigate') { e.respondWith(pageFetch(e)); return; }
  e.respondWith(assetFetch(e));
});

// /data/*.json: network first (the browser still revalidates with ETag -> 304 = nothing downloaded); a copy of every
// good answer is stored with the time, and served when the network is gone.
async function dataFetch(e) {
  const req = e.request, key = new URL(req.url).pathname;
  const cache = await caches.open(DATA);
  try {
    const res = await fetch(req);
    if (res.status === 200) {
      const copy = res.clone();
      e.waitUntil((async () => {
        const buf = await copy.arrayBuffer();
        const h = new Headers({ 'Content-Type': copy.headers.get('Content-Type') || 'application/json; charset=utf-8', 'X-SW-Cached-At': new Date().toISOString() });
        await cache.put(key, new Response(buf, { status: 200, headers: h }));
      })());
    }
    return res;
  } catch (err) {
    const hit = await cache.match(key);
    if (hit) return hit;
    return new Response(JSON.stringify({ error: 'offline' }), { status: 503, headers: { 'Content-Type': 'application/json' } });
  }
}
// pages: network first, last good copy when offline (the login page is never cached: a 401 answer is not stored)
async function pageFetch(e) {
  const req = e.request, key = new URL(req.url).pathname;
  try {
    const res = await fetch(req);
    if (res.status === 200 && (key === '/' || key === '/pnl')) { const copy = res.clone(); e.waitUntil(caches.open(SHELL).then((c) => c.put(key, copy))); }
    return res;
  } catch (err) {
    const c = await caches.open(SHELL);
    return (await c.match(key)) || (await c.match('/offline.html')) || new Response('Ngoại tuyến', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
  }
}
// code, fonts, images, icons, launch screens: cache first (file names are stable; a new build starts a new cache)
async function assetFetch(e) {
  const req = e.request;
  const c = await caches.open(SHELL);
  const hit = await c.match(req);
  if (hit) return hit;
  try {
    const res = await fetch(req);
    if (res.status === 200) e.waitUntil(c.put(req, res.clone()));
    return res;
  } catch (err) {
    return new Response('', { status: 504 });
  }
}
